INSERT INTO restaurants (id, name, slug, description, address, phone, email, logo_url, latitude, longitude, city, cuisine, website, rating) VALUES ('rest_ragno_doro_caffe', 'Ragno d\'Oro Caffe', 'ragno-d-oro-caffe', 'Caffè storico dal 1856 nel cuore di Giovinazzo. Bistrot di cucina ricercata con piatti d\'autore, ingredienti selezionati e atmosfera raffinata. Aperto tutti i giorni 8:00-23:30.', 'Piazza Vittorio Emanuele II, 67/68, 70054 Giovinazzo (BA)', NULL, NULL, 'https://www.trovapiatto.it/logo/ragno-doro-caffe.png', 41.1875738, 16.6718963, 'Giovinazzo', 'Bistrot', 'https://ragnodorocaffe.it/bistrot/', NULL);
